 ("أَيْنَ ذَهَبَ الْخَروفُ؟ 🐑","ماذا يَأْكُلُ الْخَروفُ في الْمَطْبَخِ؟ (What does the sheep eat in the kitchen?)","نَموذَجٌ: يَأْكُلُ خُبْزًا وَخِيارًا."),
 ("رِحْلَةُ خَروفي 🗺️","Read the text",[["🚪","دَخَلَ","دَخَلَ خَروفي لِلْمَطْبَخِ مِنَ الْمَدْخَلِ."],["🤔","احْتارَ","دَخَلَ وَخَرَجَ مُحْتارًا ماذا يَخْتارُ."],["🍞","ذَهَبَ","خَرَجَ مِنَ الْمَخْرَجِ، وَذَهَبَ إِلى الْمَخْبَزِ."]]),
 ("أَصِلُ الْكَلِمَةَ بِالْمَعْنى 🔤",[["مَدْخَلٌ","entrance"],["خُيوطٌ","threads"],["خَرَزٌ","beads"],["بَخورٌ","incense"]]),
