 [["دُبٌّ","bear","🐻"],["ذِئْبٌ","wolf","🐺"],["ذَهَبٌ","gold","🪙"],["دَجاجَةٌ","hen","🐔"]],
 ("دُبٌّ أَمْ ذِئْبٌ؟ 🐻🐺","ما الْفَرْقُ بَيْنَ (د) وَ(ذ)؟ (What is the difference?)","نَموذَجٌ: (ذ) فَوْقَها نُقْطَةٌ، وَ(د) بِلا نُقْطَةٍ."),
 ("الدُّبُّ وَالذِّئْبُ 🗺️","Read the text",[["🐻","الدُّبُّ","عِنْدَهُ دِرْهَمٌ عَلَيْهِ دالٌ."],["🌽","الذِّئْبُ","ذَهَبَ لِيَأْكُلَ الذُّرَةَ، وَذاقَ بُذورًا لَذيذَةً."],["💨","الدّولابُ","دارَ الدّولابُ وَطارَ الدّينارُ."]]),
